import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"震","description":"東坡易傳 - 震","frontmatter":{"title":"震","description":"東坡易傳 - 震"},"headers":[],"relativePath":"classics/dongpo/052.md","filePath":"classics/dongpo/052.md"}'),o={name:"classics/dongpo/052.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="震" tabindex="-1">震 <a class="header-anchor" href="#震" aria-label="Permalink to “震”">​</a></h1><p>“震”：亨。震來虩虩，笑言啞啞；震驚百里，不喪匕鬯。</p><p>《彖》曰：“震”，亨。“震來虩虩”，恐致福也；“笑言啞啞”，後有則也。“震驚百里”，驚遠而懼邇也。不喪匕鬯，出可以守宗廟社稷，以為祭主也。</p><p>“震”者，陽德之先，震陰而達陽者也，故“亨”。“震驚百里”，言其及遠也；“不喪七鬯”，言其和也；若震而不和，則必有僵仆隕墜者矣。“七鬯”，祭器也；必取祭器者，以見震長子也。若威而不猛，則可以為祭主矣。“出”之為言，見也。</p><p>象曰：“氵存雷，震；君子以恐懼修省。</p><p>初九：震來虩虩，後笑言啞啞，吉。象曰：“震來虩虩”，恐致福也；“笑言啞啞”，後有則也。</p><p>二陽，震物者也；四陰，見震者也。“震”之為道，以威達德者也，故可試而不可遂。試則養而無窮，遂則玩而不終。初九，試而不遂者也，以虩虩之震，而繼之以啞啞之笑，明其不常用也。惟其不常用，故二陰莫敢犯其鋒，皆以逃避而後免也。以其威之不常用，故知其所以震物者，非以害之，欲其恐而致福也。“有則”者，言其不遂也。</p><p>六二：震來，厲；億喪貝，躋於九陵，勿逐，七日得。象曰：“震來，厲”，乘剛也。</p><p>初九之威不可犯也，來則危，往則安。故雖“喪貝”而“勿逐”，“躋於九陵”以避之。以初九之不遂其震，而繼之以笑言也。故七日可以得所喪也。“喪貝”以明初九之威，“七日得”以明初九之不以威窮物也。</p><p>六三：震蘇蘇，震行無眚。象曰：“震蘇蘇”，位不當也。</p><p>六三不鄰於震矣，而猶蘇蘇然，懼也。行而避之，然後無眚，以明初九之威能及遠也。</p><p>九四：震遂泥。象曰：“震遂泥”，未光也。</p><p>震於已震之後，遂而不知止者也，故“泥”。“泥”者，以言其不能及遠也，故二陰皆以處而不避為吉。</p><p>六五：震往來，厲；億無喪，有事。象曰：“震往來，厲”，危行也；其事在中，大無喪也。</p><p>九四以其“遂泥”之威加於六五，非六五之所當畏，其衰可坐而待也。夫九四雖未可乘，然往而避之則過矣，故曰：“往來，厲。”往來皆危，則以處為安矣。九四之威既已泥矣，豈復能如初九一震而喪六二之貞哉！以六五居中，處而待之，非獨無喪，億將有功。故曰：“億無喪，有事。” 510-</p><p>上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎；婚媾有言。象曰：“震索索”，中未得也；雖兇無咎，畏鄰戒也。</p><p>九四至此，其實不能為，徒襲其餘威以加上六。上六未得其已衰之情，故猶“索索”、“矍矍”而畏之。苟畏之不已，而徵以避之，則四張而不可止矣，故兇。聖人知其不足避也，故告之曰：“震不於其躬，於其鄰”，言九四之威僅可以及五，而不及上；可以戒而無咎，無庸徵也。九四始欲以威加物，及其泥而物莫之畏也，則其及於上六者，有言而已，衰之甚也。六爻皆無應，故九四兼有二陰，得稱“婚媾”也。六二“喪貝”而五無喪，六三“震行無眚”，而上六“徵兇”，九四之不及初也遠矣。</p>',17)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
